package set;

import java.util.Set;
import java.util.TreeSet;

public class TreeSetDemo {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		
		Set<String> ts=new TreeSet<>();
		ts.add("xyz");
		ts.add("def");
		ts.add("ghi");
		ts.add("abc");
		System.out.println(ts);

	}

}
